import math


def poisson_disk(width, height, radius, candidates, rand, k=30, start=None):
    if radius <= 0:
        raise ValueError("radius must be positive")
    if width <= 0 or height <= 0:
        raise ValueError("the domain must have positive extent")
    cell = radius / math.sqrt(2)
    cols = int(math.ceil(width / cell))
    rows = int(math.ceil(height / cell))
    grid = {}

    def cell_of(point):
        return int(point[0] / cell), int(point[1] / cell)

    def fits(point):
        if not (0 <= point[0] < width and 0 <= point[1] < height):
            return False
        gx, gy = cell_of(point)
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                other = grid.get((gx + dx, gy + dy))
                if other is None:
                    continue
                if math.hypot(other[0] - point[0], other[1] - point[1]) < radius:
                    return False
        return True

    first = start if start is not None else (width / 2, height / 2)
    if not fits(first):
        raise ValueError("the starting point is outside the domain")
    points = [first]
    grid[cell_of(first)] = first
    active = [first]
    while active:
        index = rand(len(active))
        origin = active[index]
        placed = False
        for _ in range(k):
            candidate = candidates(origin, radius)
            if fits(candidate):
                points.append(candidate)
                grid[cell_of(candidate)] = candidate
                active.append(candidate)
                placed = True
                break
        if not placed:
            active.pop(index)
    return points
